import type { SubmissionOptions } from "@kasperrt/smolter/preact";

const options: SubmissionOptions = {
  action: "/tasks/7",
  method: "PATCH",
  encType: "application/json",
};

import { readSubmission } from "@kasperrt/smolter/preact";
import type { ActionFunctionArgs } from "@kasperrt/smolter/preact";

export async function action({ request }: ActionFunctionArgs) {
  const input = await readSubmission(request);

  return { received: input };
}
